export const definitionBySlug: Record<string, DefinitionEntry> = Object.fromEntries(
  definitions.map((d) => [d.slug, d]),
)

/** slug로 정의 항목 조회 (없으면 undefined) */
export function getDefinition(slug: string): DefinitionEntry | undefined {
  return definitionBySlug[slug]
}
